/*
 * A248372  Numbers m such that both p = 52*m + 1 and q = 52*p + 1 are prime.
 * https://oeis.org/A248372
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) is the n‑th integer m such that p=52*m+1 and q=52*p+1 are
 *            prime
 * Range:     u8 n <= 7, u16 n <= 785, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   is_prime
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The values are generated by scanning multiples of 3 (all solutions are divisible by 3)
   and testing the primality of p and q using the provided is_prime function. */

#include <stdlib.h>
#include <stdbool.h>

#include "../utils/is_prime.h"    /* bool is_prime(idx_t x); */

static seq_t *cache = NULL;      /* memoised sequence values   */
static size_t cache_len = 0;     /* number of terms stored     */
static size_t cache_cap = 0;     /* allocated capacity         */
static idx_t next_candidate = 3; /* next m to test (always ≡0 mod 3) */

/* ensure capacity at least 'need' */
static void ensure_capacity(size_t need)
{
    if (cache_cap >= need)
        return;
    size_t new_cap = cache_cap ? cache_cap * 2 : 16;
    if (new_cap < need)
        new_cap = need;
    seq_t *new_cache = (seq_t *)malloc(new_cap * sizeof(seq_t));
    if (!new_cache) {
        /* Allocation failure: abort (cannot recover). */
        abort();
    }
    if (cache) {
        for (size_t i = 0; i < cache_len; ++i)
            new_cache[i] = cache[i];
        free(cache);
    }
    cache = new_cache;
    cache_cap = new_cap;
}

seq_t a(idx_t n)
{
    if (n < 1)
        return (seq_t)0;                /* Offset is 1, below that is unspecified */

    /* Return cached value if available */
    if ((size_t)n <= cache_len)
        return cache[n - 1];

    /* Generate terms until we have n terms */
    while (cache_len < (size_t)n) {
        idx_t m = next_candidate;          /* candidate m (multiple of 3) */
        idx_t p = 52 * m + 1;               /* p = 52*m + 1          */
        if (!is_prime(p)) {                 /* p not prime → skip */
            next_candidate += 3;
            continue;
        }
        idx_t q = 52 * p + 1;               /* q = 52*p + 1          */
        if (!is_prime(q)) {                 /* q not prime → skip */
            next_candidate += 3;
            continue;
        }

        /* Store the valid m in the cache */
        ensure_capacity(cache_len + 1);
        cache[cache_len++] = (seq_t)m;
        next_candidate += 3;
    }

    return cache[n - 1];
}
